<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/bootstrap.php';

use Azoz\Auth;
use Azoz\Database;

$db = Database::connection();
$route = (string)($_GET['r'] ?? 'home');
$user = Auth::user();

function h(?string $v): string { return e($v); }
function go(string $r = 'home'): never { redirect('/?r=' . $r); }
function require_user(): array { return Auth::requireAuth(); }
function require_admin(): array { return Auth::requireAuth('admin'); }
function post_csrf(): void { if ($_SERVER['REQUEST_METHOD'] !== 'POST' || !verify_csrf($_POST['_csrf'] ?? null)) { http_response_code(419); exit('انتهت صلاحية الطلب.'); } }
function q(string $sql, array $params = []): array { $s = Database::connection()->prepare($sql); $s->execute($params); return $s->fetchAll(); }
function one(string $sql, array $params = []): ?array { $s = Database::connection()->prepare($sql); $s->execute($params); $row = $s->fetch(); return $row ?: null; }
function execq(string $sql, array $params = []): void { $s = Database::connection()->prepare($sql); $s->execute($params); }
function badge(string $value): string { return '<span class="badge">' . h($value) . '</span>'; }
function csrf(): string { return '<input type="hidden" name="_csrf" value="' . h(csrf_token()) . '">'; }
function page(string $title, string $body, ?array $user = null): never {
    $roleLinks = $user ? ($user['role']==='admin' ? '<a href="/?r=invite">دعوات</a><a href="/?r=deliveries">تسليمات</a>' : ($user['role']==='client' ? '<a href="/?r=client_quotes">العروض</a><a href="/?r=deliveries">التسليمات</a>' : '<a href="/?r=deliveries">التسليمات</a>')) : '';
    $nav = $user ? '<span class="user-chip">' . h($user['full_name']) . '</span>' . $roleLinks . '<a href="/?r=dashboard">لوحتي</a><a href="/logout.php">خروج</a>' : '<a href="/login.php">تسجيل الدخول</a><a class="button button-small" href="/?r=register">إنشاء حساب</a>';
    $flash = flash('ok'); $err = flash('error');
    echo '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' . h($title) . ' · Azoz Software</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="site-header"><a href="/"><strong>Azoz Software</strong></a><nav>' . $nav . '</nav></header><main class="container app-main">';
    if ($flash) echo '<div class="notice">' . h($flash) . '</div>';
    if ($err) echo '<div class="error">' . h($err) . '</div>';
    echo $body . '</main><footer class="site-footer">Azoz Software · منصة إدارة وكالة برمجيات</footer></body></html>'; exit;
}
function form(string $action, string $fields, string $button): string { $encoding = $action === 'upload_file' ? ' enctype="multipart/form-data"' : ''; return '<form method="post" action="/?r=' . h($action) . '"' . $encoding . '>' . csrf() . $fields . '<button class="button button-primary" type="submit">' . h($button) . '</button></form>'; }

if ($route === 'register') {
    if ($user) go('dashboard');
    $error = null;
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        if (!verify_csrf($_POST['_csrf'] ?? null)) $error = 'انتهت صلاحية النموذج.';
        $name = trim((string)($_POST['full_name'] ?? '')); $email = strtolower(trim((string)($_POST['email'] ?? ''))); $pass = (string)($_POST['password'] ?? '');
        if (!$error && ((function_exists('mb_strlen') ? mb_strlen($name) : strlen($name)) < 2 || !filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($pass) < 8)) $error = 'أدخل الاسم والبريد وكلمة مرور من 8 أحرف على الأقل.';
        if (!$error && one('SELECT id FROM users WHERE email = :email', ['email' => $email])) $error = 'البريد مستخدم مسبقًا.';
        if (!$error) {
            $db->beginTransaction();
            try { $s=$db->prepare("INSERT INTO users(full_name,email,password_hash,role,status) VALUES(:n,:e,:p,'client','pending_verification')"); $s->execute(['n'=>$name,'e'=>$email,'p'=>password_hash($pass,PASSWORD_DEFAULT)]); $uid=(int)$db->lastInsertId(); $raw=bin2hex(random_bytes(32)); execq('INSERT INTO email_verifications(user_id,token_hash,expires_at) VALUES(:u,:t,DATE_ADD(NOW(),INTERVAL 24 HOUR))',['u'=>$uid,'t'=>hash('sha256',$raw)]); $db->commit(); @file_put_contents(__DIR__.'/../storage/logs/mail.log', date('c')." verification for {$email}: /?r=verify&token={$raw}\n", FILE_APPEND); page('تم إنشاء الحساب','<section class="card narrow"><h1>تم إنشاء الحساب</h1><p>تم إنشاء حسابك، ويحتاج إلى تأكيد البريد الإلكتروني قبل الدخول.</p><p class="muted">في بيئة الإنتاج يجب ضبط SMTP. رابط التحقق سُجل في سجل البريد المحلي للبيئة التجريبية.</p><a class="button button-primary" href="/login.php">الانتقال للدخول</a></section>',$user); } catch(Throwable $e) { if($db->inTransaction())$db->rollBack(); $error='تعذر إنشاء الحساب. حاول مرة أخرى.'; }
        }
    }
    $body='<section class="card narrow"><span class="eyebrow">CLIENT REGISTRATION</span><h1>إنشاء حساب عميل</h1><p class="muted">التسجيل العام ينشئ حساب عميل فقط.</p>'.($error?'<div class="error">'.h($error).'</div>':'').form('register','<label>الاسم الكامل<input name="full_name" required value="'.h($_POST['full_name']??'').'"></label><label>البريد الإلكتروني<input type="email" name="email" required value="'.h($_POST['email']??'').'"></label><label>كلمة المرور<input type="password" name="password" minlength="8" required></label>','إنشاء الحساب').'</section>';
    page('إنشاء حساب',$body,$user);
}

if ($route === 'verify') {
    $token = (string)($_GET['token'] ?? ''); $row = one('SELECT * FROM email_verifications WHERE token_hash=:t AND used_at IS NULL AND expires_at>NOW()', ['t'=>hash('sha256',$token)]);
    if ($row) { execq('UPDATE email_verifications SET used_at=NOW() WHERE id=:id',['id'=>$row['id']]); execq("UPDATE users SET status='active',email_verified_at=NOW() WHERE id=:id",['id'=>$row['user_id']]); page('تم التحقق','<section class="card narrow"><h1>تم تأكيد البريد</h1><p>يمكنك الآن تسجيل الدخول إلى حسابك.</p><a class="button button-primary" href="/login.php">تسجيل الدخول</a></section>',$user); }
    page('رابط غير صالح','<section class="card narrow"><h1>رابط التحقق غير صالح</h1><p>قد يكون الرابط منتهيًا أو مستخدمًا.</p><a href="/?r=register">العودة للتسجيل</a></section>',$user);
}

if ($route === 'setup') {
    if (one("SELECT id FROM users WHERE role='admin'")) page('التهيئة مكتملة','<section class="card narrow"><h1>تمت تهيئة النظام</h1><p>تم تعطيل إنشاء المدير الأول لأن حسابًا إداريًا موجود بالفعل.</p><a href="/login.php">تسجيل الدخول</a></section>',$user);
    $error=null;
    if ($_SERVER['REQUEST_METHOD']==='POST') { post_csrf(); $key=(string)($_POST['setup_key']??''); $expected=getenv('SETUP_KEY')?:''; $name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??''); if(!$expected||!hash_equals($expected,$key))$error='مفتاح التهيئة غير صحيح.'; elseif(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<12||(function_exists('mb_strlen')?mb_strlen($name):strlen($name))<2)$error='تحقق من البيانات وكلمة المرور (12 حرفًا على الأقل).'; else {execq("INSERT INTO users(full_name,email,password_hash,role,status,email_verified_at) VALUES(:n,:e,:p,'admin','active',NOW())",['n'=>$name,'e'=>$email,'p'=>password_hash($pass,PASSWORD_DEFAULT)]); page('تم إنشاء المدير','<section class="card narrow"><h1>تم إنشاء المدير الأول</h1><p>احذف أو غيّر مفتاح التهيئة بعد الدخول.</p><a class="button button-primary" href="/login.php">تسجيل الدخول</a></section>',$user);}}
    $body='<section class="card narrow"><span class="eyebrow">ONE-TIME SETUP</span><h1>تهيئة المدير الأول</h1><p class="muted">اضبط SETUP_KEY في ملف البيئة قبل استخدام هذه الصفحة.</p>'.($error?'<div class="error">'.h($error).'</div>':'').form('setup','<label>مفتاح التهيئة<input type="password" name="setup_key" required></label><label>الاسم الكامل<input name="full_name" required></label><label>البريد الإلكتروني<input type="email" name="email" required></label><label>كلمة مرور المدير<input type="password" name="password" minlength="12" required></label>','إنشاء المدير').'</section>'; page('تهيئة المدير',$body,$user);
}

if ($route === 'home') {
    $body='<section class="hero"><span class="eyebrow">SOFTWARE AGENCY PLATFORM</span><h1>إدارة احترافية لدورة تطوير مشاريعك</h1><p>من طلب المشروع وعرض السعر إلى المهام والتسليمات، في مساحة واحدة آمنة ومنظمة.</p><div class="hero-actions"><a class="button button-primary" href="/?r=register">ابدأ بطلب مشروع</a><a class="button button-ghost" href="/login.php">دخول المنصة</a></div></section><section class="feature-grid"><article class="card"><h3>طلبات وعروض</h3><p>نظّم طلبات العملاء وإصدارات عروض الأسعار وقرارات القبول.</p></article><article class="card"><h3>مشاريع ومهام</h3><p>وزّع العمل على المطورين وراجع الإنجاز قبل الاعتماد.</p></article><article class="card"><h3>ملفات ومالية</h3><p>حافظ على الملفات والتسليمات والسجلات المالية في سياقها الصحيح.</p></article></section>'; page('الرئيسية',$body,$user);
}

if ($route === 'dashboard') {
    $u=require_user(); $body='<div class="page-heading"><div><span class="eyebrow">WORKSPACE</span><h1>لوحة '.($u['role']==='admin'?'المدير':($u['role']==='developer'?'المطور':'العميل')).'</h1><p class="muted">مرحبًا '.h($u['full_name']).'</p></div></div>';
    if ($u['role']==='admin') {
        $counts=[['العملاء',one("SELECT COUNT(*) c FROM users WHERE role='client'")['c']],['الطلبات الجديدة',one("SELECT COUNT(*) c FROM project_requests WHERE status='new'")['c']],['المشاريع الجارية',one("SELECT COUNT(*) c FROM projects WHERE status='in_progress'")['c']],['المهام المعلقة',one("SELECT COUNT(*) c FROM tasks WHERE status IN ('new','in_progress','pending_review','changes_requested')")['c']]]; $body.='<div class="stat-grid">';foreach($counts as $c)$body.='<div class="stat card"><span>'.h($c[0]).'</span><strong>'.h((string)$c[1]).'</strong></div>'; $body.='</div><div class="two-col"><section class="card"><h2>طلبات المشاريع</h2><a class="button button-primary button-small" href="/?r=requests">إدارة الطلبات</a><a class="button button-ghost button-small" href="/?r=quotations">عروض الأسعار</a></section><section class="card"><h2>التشغيل</h2><a class="button button-ghost button-small" href="/?r=projects">المشاريع</a><a class="button button-ghost button-small" href="/?r=finance">المالية</a><a class="button button-ghost button-small" href="/?r=users">المستخدمون</a></section></div>';
    } elseif($u['role']==='client') { $body.='<div class="two-col"><section class="card"><h2>طلب جديد</h2>'.form('create_request','<label>عنوان المشروع<input name="title" required></label><label>نوع الخدمة<input name="service_type" required placeholder="موقع، تطبيق، نظام..."></label><label>الوصف<textarea name="description" required></textarea></label><label>الميزانية الاختيارية<input name="budget_amount" type="number" step="0.01"></label><label>العملة<input name="currency" value="USD" maxlength="3"></label>','إرسال الطلب').'</section><section class="card"><h2>طلباتي</h2>';foreach(q('SELECT * FROM project_requests WHERE client_id=:c ORDER BY created_at DESC',['c'=>$u['id']]) as $r)$body.='<div class="list-row"><strong>'.h($r['title']).'</strong>'.badge($r['status']).'</div>'; $body.='</section></div><section class="card"><h2>مشاريعي</h2>';foreach(q('SELECT * FROM projects WHERE client_id=:c ORDER BY created_at DESC',['c'=>$u['id']]) as $p)$body.='<div class="list-row"><strong>'.h($p['name']).'</strong>'.badge($p['status']).'<a href="/?r=project&id='.$p['id'].'">فتح</a></div>'; $body.='</section>';
    } else { $body.='<section class="card"><h2>المهام المسندة إليك</h2>';foreach(q('SELECT t.*,p.name project_name FROM tasks t JOIN projects p ON p.id=t.project_id WHERE t.assigned_to=:u ORDER BY t.due_date IS NULL,t.due_date',['u'=>$u['id']]) as $t)$body.='<div class="list-row"><strong>'.h($t['title']).'</strong><span>'.h($t['project_name']).'</span>'.badge($t['status']).'<a href="/?r=task&id='.$t['id'].'">فتح</a></div>'; $body.='</section>';}
    page('لوحة التحكم',$body,$u);
}

if ($route === 'create_request') { $u=Auth::requireAuth('client'); post_csrf(); $title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$type=trim((string)($_POST['service_type']??''));$budget=$_POST['budget_amount']!==''?(float)$_POST['budget_amount']:null;$cur=strtoupper(trim((string)($_POST['currency']??'USD')));$currency=one('SELECT id FROM currencies WHERE code=:c AND is_active=1',['c'=>$cur])?:one("SELECT id FROM currencies WHERE code='USD'"); if($title&&$desc&&$type){execq('INSERT INTO project_requests(client_id,title,description,service_type,budget_amount,currency_id) VALUES(:c,:t,:d,:s,:b,:cur)',['c'=>$u['id'],'t'=>$title,'d'=>$desc,'s'=>$type,'b'=>$budget,'cur'=>$currency['id']]);flash('ok','تم إرسال طلب المشروع.');}else flash('error','أكمل الحقول المطلوبة.');go('dashboard'); }

if ($route === 'requests') { $u=require_admin(); $rows=q('SELECT r.*,u.full_name client_name FROM project_requests r JOIN users u ON u.id=r.client_id ORDER BY r.created_at DESC');$body='<div class="page-heading"><h1>طلبات المشاريع</h1><a href="/?r=dashboard">العودة للوحة</a></div><section class="card table-wrap"><table><thead><tr><th>العنوان</th><th>العميل</th><th>الخدمة</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>';foreach($rows as $r)$body.='<tr><td>'.h($r['title']).'</td><td>'.h($r['client_name']).'</td><td>'.h($r['service_type']).'</td><td>'.badge($r['status']).'</td><td>'.form('update_request','<input type="hidden" name="id" value="'.$r['id'].'"><select name="status"><option>new</option><option>reviewing</option><option>waiting_info</option><option>qualified</option><option>rejected</option><option>cancelled</option></select><input name="rejection_reason" placeholder="سبب الرفض إن وجد">','حفظ').'</td></tr>'; $body.='</tbody></table></section>';page('طلبات المشاريع',$body,$u); }
if ($route === 'update_request') { $u=require_admin();post_csrf();$status=(string)$_POST['status'];$allowed=['new','reviewing','waiting_info','qualified','rejected','cancelled'];if(in_array($status,$allowed,true))execq('UPDATE project_requests SET status=:s,rejection_reason=:r WHERE id=:id',['s'=>$status,'r'=>trim((string)($_POST['rejection_reason']??'')),'id'=>(int)$_POST['id']]);flash('ok','تم تحديث الطلب.');go('requests'); }

if ($route === 'quotations') { $u=require_admin();$requests=q("SELECT r.id,r.title,u.full_name FROM project_requests r JOIN users u ON u.id=r.client_id WHERE r.status='qualified' ORDER BY r.created_at DESC");$quotes=q('SELECT q.*,r.title,cur.code FROM quotations q JOIN project_requests r ON r.id=q.request_id JOIN currencies cur ON cur.id=q.currency_id ORDER BY q.created_at DESC');$body='<div class="page-heading"><h1>عروض الأسعار</h1></div><section class="card"><h2>إنشاء عرض</h2>'.form('create_quotation','<label>الطلب<select name="request_id" required><option value="">اختر طلبًا مؤهلًا</option>'.implode('',array_map(fn($r)=>'<option value="'.$r['id'].'">'.h($r['title'].' — '.$r['full_name']).'</option>',$requests)).'</select></label><label>نطاق العمل<textarea name="scope" required></textarea></label><div class="form-grid"><label>السعر<input name="amount" type="number" step="0.01" required></label><label>العملة<input name="currency" value="USD" maxlength="3"></label><label>المدة<input name="duration" required></label><label>الصلاحية بالأيام<input name="days" type="number" value="14"></label></div><label>شروط الدفع<textarea name="payment_terms"></textarea></label><label>شروط التسليم<textarea name="delivery_terms"></textarea></label>','إرسال العرض').'</section><section class="card"><h2>الإصدارات</h2><div class="table-wrap"><table><tr><th>الطلب</th><th>الإصدار</th><th>المبلغ</th><th>الحالة</th><th>القرار</th></tr>';foreach($quotes as $q)$body.='<tr><td>'.h($q['title']).'</td><td>'.h((string)$q['version_number']).'</td><td>'.h($q['total_amount'].' '.$q['code']).'</td><td>'.badge($q['status']).'</td><td>'.($q['status']==='sent'?'بانتظار العميل':'—').'</td></tr>'; $body.='</table></div></section>';page('عروض الأسعار',$body,$u); }
if ($route === 'create_quotation') { $u=require_admin();post_csrf();$rid=(int)$_POST['request_id'];$req=one('SELECT * FROM project_requests WHERE id=:id',['id'=>$rid]);if($req){$last=one('SELECT MAX(version_number) v FROM quotations WHERE request_id=:r',['r'=>$rid]);$cur=one('SELECT id FROM currencies WHERE code=:c',['c'=>strtoupper(trim((string)$_POST['currency']))])?:one("SELECT id FROM currencies WHERE code='USD'");$expires=(new DateTimeImmutable('now'))->modify('+'.max(1,(int)$_POST['days']).' days')->format('Y-m-d H:i:s');execq('UPDATE quotations SET status="superseded" WHERE request_id=:r AND status IN ("sent","draft")',['r'=>$rid]);execq('INSERT INTO quotations(request_id,version_number,created_by,scope_description,total_amount,currency_id,estimated_duration,payment_terms,delivery_terms,status,sent_at,expires_at) VALUES(:r,:v,:u,:s,:a,:c,:d,:p,:dt,"sent",NOW(),:ex)',['r'=>$rid,'v'=>(int)($last['v']??0)+1,'u'=>$u['id'],'s'=>trim((string)$_POST['scope']),'a'=>(float)$_POST['amount'],'c'=>$cur['id'],'d'=>trim((string)$_POST['duration']),'p'=>trim((string)$_POST['payment_terms']),'dt'=>trim((string)$_POST['delivery_terms']),'ex'=>$expires]);flash('ok','تم إنشاء وإرسال عرض السعر.');}go('quotations'); }

if ($route === 'projects') { $u= require_admin();$rows=q('SELECT p.*,u.full_name client_name FROM projects p JOIN users u ON u.id=p.client_id ORDER BY p.created_at DESC');$body='<div class="page-heading"><h1>المشاريع</h1></div><section class="card table-wrap"><table><tr><th>المشروع</th><th>العميل</th><th>الحالة</th><th>التقدم</th><th></th></tr>';foreach($rows as $p){$total=(int)one('SELECT COUNT(*) c FROM tasks WHERE project_id=:p',['p'=>$p['id']])['c'];$done=(int)one("SELECT COUNT(*) c FROM tasks WHERE project_id=:p AND status='completed'",['p'=>$p['id']])['c'];$body.='<tr><td>'.h($p['name']).'</td><td>'.h($p['client_name']).'</td><td>'.badge($p['status']).'</td><td>'.($total?round($done/$total*100):0).'%</td><td><a href="/?r=project&id='.$p['id'].'">فتح</a></td></tr>';}$body.='</table></section>';page('المشاريع',$body,$u); }
if ($route === 'project') { $u=require_user();$id=(int)($_GET['id']??0);$p=one('SELECT p.*,u.full_name client_name FROM projects p JOIN users u ON u.id=p.client_id WHERE p.id=:id',['id'=>$id]);if(!$p||($u['role']==='client'&&$p['client_id']!=$u['id'])||($u['role']==='developer'&&!one('SELECT id FROM project_members WHERE project_id=:p AND user_id=:u AND removed_at IS NULL',['p'=>$id,'u'=>$u['id']]))){http_response_code(403);exit('Forbidden');}$tasks=q('SELECT t.*,u.full_name assignee FROM tasks t JOIN users u ON u.id=t.assigned_to WHERE t.project_id=:p ORDER BY t.created_at DESC',['p'=>$id]);$body='<div class="page-heading"><div><h1>'.h($p['name']).'</h1><p>'.h($p['description']).'</p></div>'.badge($p['status']).'</div><section class="card"><h2>المهام</h2>';foreach($tasks as $t)$body.='<div class="list-row"><strong>'.h($t['title']).'</strong><span>'.h($t['assignee']).'</span>'.badge($t['status']).'<a href="/?r=task&id='.$t['id'].'">فتح</a></div>';if($u['role']==='admin')$body.='<h3>إضافة مطور إلى المشروع</h3>'.form('add_member','<input type="hidden" name="project_id" value="'.$id.'"><label>معرف المطور<input name="user_id" type="number" required></label>','إضافة العضو').form('create_task','<input type="hidden" name="project_id" value="'.$id.'"><label>عنوان المهمة<input name="title" required></label><label>الوصف<textarea name="description" required></textarea></label><label>معرف المطور المسند<input name="assigned_to" type="number" required></label><label>الموعد النهائي<input name="due_date" type="date"></label>','إضافة مهمة');$body.='</section><section class="card"><h2>المراسلات</h2><form method="post" action="/?r=message">'.csrf().'<input type="hidden" name="project_id" value="'.$id.'"><textarea name="message" required placeholder="اكتب رسالة..."></textarea><button class="button button-primary" type="submit">إرسال</button></form></section>';page('تفاصيل المشروع',$body,$u); }
if ($route === 'create_task') { $u=require_admin();post_csrf();$pid=(int)$_POST['project_id'];$member=one('SELECT id FROM project_members WHERE project_id=:p AND user_id=:u AND removed_at IS NULL',['p'=>$pid,'u'=>(int)$_POST['assigned_to']]);if(!$member) {flash('error','المطور ليس عضوًا في المشروع. أضف العضو أولًا.');go('project&id='.$pid);}execq('INSERT INTO tasks(project_id,assigned_to,created_by,title,description,due_date) VALUES(:p,:a,:c,:t,:d,:due)',['p'=>$pid,'a'=>(int)$_POST['assigned_to'],'c'=>$u['id'],'t'=>trim((string)$_POST['title']),'d'=>trim((string)$_POST['description']),'due'=>$_POST['due_date']?:null]);flash('ok','تم إنشاء المهمة.');go('project&id='.$pid); }
if ($route === 'task') { $u=require_user();$id=(int)$_GET['id'];$t=one('SELECT t.*,p.name project_name FROM tasks t JOIN projects p ON p.id=t.project_id WHERE t.id=:id',['id'=>$id]);if(!$t||($u['role']==='developer'&&$t['assigned_to']!=$u['id'])){http_response_code(403);exit('Forbidden');}$body='<div class="page-heading"><h1>'.h($t['title']).'</h1>'.badge($t['status']).'</div><section class="card"><p>'.nl2br(h($t['description'])).'</p><p class="muted">المشروع: '.h($t['project_name']).'</p>';if($u['role']==='developer')$body.=form('upload_file','<input type="hidden" name="task_id" value="'.$id.'"><label>ملف العمل<input type="file" name="attachment" required></label>','رفع الملف').form('update_task','<input type="hidden" name="id" value="'.$id.'"><label>الحالة<select name="status"><option>in_progress</option><option>blocked</option><option>pending_review</option></select></label>','تحديث المهمة');if($u['role']==='admin')$body.=form('review_task','<input type="hidden" name="id" value="'.$id.'"><label>قرار المراجعة<select name="decision"><option value="approved">اعتماد</option><option value="changes_requested">طلب تعديل</option></select></label><label>الملاحظات<textarea name="comments" required></textarea></label>','حفظ المراجعة');$body.='</section>';page('تفاصيل المهمة',$body,$u); }
if ($route === 'update_task') { $u=Auth::requireAuth('developer');post_csrf();$t=one('SELECT * FROM tasks WHERE id=:id AND assigned_to=:u',['id'=>(int)$_POST['id'],'u'=>$u['id']]);if($t){$status=(string)$_POST['status'];if(in_array($status,['in_progress','blocked','pending_review'],true))execq('UPDATE tasks SET status=:s,submitted_at=IF(:s2="pending_review",NOW(),submitted_at) WHERE id=:id',['s'=>$status,'s2'=>$status,'id'=>$t['id']]);}go('task&id='.(int)$_POST['id']); }
if ($route === 'review_task') { $u=require_admin();post_csrf();$t=one('SELECT * FROM tasks WHERE id=:id',['id'=>(int)$_POST['id']]);if($t){$d=(string)$_POST['decision'];$status=$d==='approved'?'completed':'changes_requested';execq('UPDATE tasks SET status=:s,completed_at=IF(:s2="completed",NOW(),NULL) WHERE id=:id',['s'=>$status,'s2'=>$status,'id'=>$t['id']]);execq('INSERT INTO task_reviews(task_id,reviewed_by,decision,comments) VALUES(:t,:u,:d,:c)',['t'=>$t['id'],'u'=>$u['id'],'d'=>$d,'c'=>trim((string)$_POST['comments'])]);}go('task&id='.(int)$_POST['id']); }
if ($route === 'message') { $u=require_user();post_csrf();$pid=(int)$_POST['project_id'];$p=one('SELECT * FROM projects WHERE id=:p',['p'=>$pid]);if(!$p){go('dashboard');}$conv=one('SELECT * FROM conversations WHERE project_id=:p LIMIT 1',['p'=>$pid]);if(!$conv){execq('INSERT INTO conversations(project_id,created_by) VALUES(:p,:u)',['p'=>$pid,'u'=>$u['id']]);$conv=one('SELECT * FROM conversations WHERE project_id=:p LIMIT 1',['p'=>$pid]);}if(!$conv||($u['role']==='client'&&$p['client_id']!=$u['id'])||($u['role']==='developer'&&!one('SELECT id FROM project_members WHERE project_id=:p AND user_id=:u AND removed_at IS NULL',['p'=>$pid,'u'=>$u['id']]))){http_response_code(403);exit('Forbidden');}execq('INSERT INTO conversation_members(conversation_id,user_id) VALUES(:c,:u) ON DUPLICATE KEY UPDATE left_at=NULL',['c'=>$conv['id'],'u'=>$u['id']]);execq('INSERT INTO messages(conversation_id,sender_id,message_body) VALUES(:c,:u,:m)',['c'=>$conv['id'],'u'=>$u['id'],'m'=>trim((string)$_POST['message'])]);flash('ok','تم إرسال الرسالة.');go('project&id='.$pid); }
if ($route === 'finance') { $u=require_admin();$rows=q('SELECT f.*,p.name project_name,c.code FROM financial_transactions f LEFT JOIN projects p ON p.id=f.project_id JOIN currencies c ON c.id=f.currency_id ORDER BY f.transaction_date DESC');$projects=q('SELECT id,name FROM projects ORDER BY name');$body='<div class="page-heading"><h1>المالية</h1></div><section class="card">'.form('add_finance','<div class="form-grid"><label>النوع<select name="type"><option value="payment">دفعة</option><option value="expense">مصروف</option></select></label><label>المبلغ<input name="amount" type="number" step="0.01" required></label><label>العملة<input name="currency" value="USD" maxlength="3"></label><label>التاريخ<input name="date" type="date" value="'.date('Y-m-d').'" required></label></div><label>المشروع<select name="project_id"><option value="">عام</option>'.implode('',array_map(fn($p)=>'<option value="'.$p['id'].'">'.h($p['name']).'</option>',$projects)).'</select></label><label>الوصف<textarea name="description" required></textarea></label>','تسجيل العملية').'</section><section class="card table-wrap"><table><tr><th>التاريخ</th><th>النوع</th><th>المشروع</th><th>المبلغ</th></tr>';foreach($rows as $r)$body.='<tr><td>'.h($r['transaction_date']).'</td><td>'.h($r['transaction_type']).'</td><td>'.h($r['project_name']??'عام').'</td><td>'.h($r['amount'].' '.$r['code']).'</td></tr>';$body.='</table></section>';page('المالية',$body,$u); }
if ($route === 'add_finance') { $u=require_admin();post_csrf();$c=one('SELECT id FROM currencies WHERE code=:c',['c'=>strtoupper(trim((string)$_POST['currency']))])?:one("SELECT id FROM currencies WHERE code='USD'");execq('INSERT INTO financial_transactions(project_id,created_by,transaction_type,amount,currency_id,transaction_date,description) VALUES(:p,:u,:t,:a,:c,:d,:x)',['p'=>$_POST['project_id']?:null,'u'=>$u['id'],'t'=>$_POST['type'],'a'=>(float)$_POST['amount'],'c'=>$c['id'],'d'=>$_POST['date'],'x'=>trim((string)$_POST['description'])]);flash('ok','تم تسجيل العملية المالية.');go('finance'); }
if ($route === 'users') { $u=require_admin();$rows=q("SELECT id,full_name,email,role,status,created_at FROM users ORDER BY created_at DESC");$body='<div class="page-heading"><h1>المستخدمون</h1></div><section class="card table-wrap"><table><tr><th>الاسم</th><th>البريد</th><th>الدور</th><th>الحالة</th><th>إجراء</th></tr>';foreach($rows as $r)$body.='<tr><td>'.h($r['full_name']).'</td><td>'.h($r['email']).'</td><td>'.h($r['role']).'</td><td>'.badge($r['status']).'</td><td>'.($r['id']!=$u['id']?form('toggle_user','<input type="hidden" name="id" value="'.$r['id'].'"><input type="hidden" name="status" value="'.($r['status']==='suspended'?'active':'suspended').'">','تغيير الحالة'):'الحساب الحالي').'</td></tr>'; $body.='</table></section>';page('المستخدمون',$body,$u); }
if ($route === 'toggle_user') { $u=require_admin();post_csrf();$id=(int)$_POST['id'];if($id!==$u['id'])execq('UPDATE users SET status=:s WHERE id=:id',['s'=>$_POST['status']==='active'?'active':'suspended','id'=>$id]);flash('ok','تم تحديث حالة الحساب.');go('users'); }
